import base64,json
from pathlib import Path
p=Path(__file__).parent
data=base64.b64encode((p/'atlas.png').read_bytes()).decode()
items=json.loads((p/'items.json').read_text())
html='''<!doctype html><meta charset="utf-8"><title>Tethium — 256 направлений</title><style>
body{margin:24px;background:#191c23;color:#eee;font:15px system-ui}h1{font-size:24px;margin-bottom:8px}p{color:#adb6c7}button{color:inherit;cursor:pointer}#grid{display:grid;grid-template-columns:repeat(16,minmax(58px,1fr));gap:5px;min-width:1008px}.cell{background:#282e39;border:1px solid #424957;border-radius:6px;padding:3px}.icon{aspect-ratio:1;background-image:url(data:image/png;base64,DATA);background-size:1600% 1600%;background-repeat:no-repeat}.label{display:block;font-size:10px;margin-top:3px;color:#bdc5d5}.cell:hover{border-color:#85b8ff;background:#3b4555}.cell.selected{border-color:#ffc56b;background:#4b412f}dialog{background:#282e39;color:white;border:1px solid #75839b;border-radius:16px;width:340px}dialog::backdrop{background:#000a}#large{width:280px;margin:auto}#close{float:right}#chosen{position:sticky;top:0;background:#191c23;padding:12px 0;z-index:1}#theme{background:#384252;border:0;border-radius:5px;padding:8px}
</style><h1>Tethium · 256 направлений иконки</h1><p>16 × 16. Нажмите на иконку для увеличения. Координаты: строка–столбец. Эскизы для выбора направления; увеличение показывает исходную детализацию.</p><button id="theme">Светлый / тёмный фон</button><div id="chosen">Выбранные: —</div><div id="grid"></div><dialog id="dialog"><button id="close">✕</button><h2 id="title"></h2><div class="icon" id="large"></div><p id="concept"></p><button id="pick">Выбрать / убрать</button></dialog><script>
const items=ITEMS,selected=new Set();let active=0;const grid=document.getElementById('grid'),dialog=document.getElementById('dialog');
items.forEach((item,i)=>{let b=document.createElement('button');b.className='cell';b.innerHTML='<div class="icon" style="background-position:'+((i%16)/15*100)+'% '+(Math.floor(i/16)/15*100)+'%"></div><span class="label">'+item.id+'</span>';b.onclick=()=>{active=i;document.getElementById('title').textContent=item.id;document.getElementById('concept').textContent=item.description;document.getElementById('large').style.backgroundPosition=((i%16)/15*100)+'% '+(Math.floor(i/16)/15*100)+'%';dialog.showModal()};grid.append(b)});
document.getElementById('close').onclick=()=>dialog.close();document.getElementById('pick').onclick=()=>{selected.has(active)?selected.delete(active):selected.add(active);grid.children[active].classList.toggle('selected',selected.has(active));document.getElementById('chosen').textContent='Выбранные: '+([...selected].sort((a,b)=>a-b).map(i=>items[i].id).join(', ')||'—')};let light=false;document.getElementById('theme').onclick=()=>{light=!light;document.querySelectorAll('.cell').forEach(e=>e.style.background=light?'#edf0f5':'');document.getElementById('large').style.backgroundColor=light?'#edf0f5':''};
</script>'''.replace('DATA',data).replace('ITEMS',json.dumps(items))
(p/'index.html').write_text(html,encoding='utf-8')
print('Created self-contained 16x16 preview, 256 cells')
